insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"noun_repair_shop_homework_q01_finish","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\noun_repair_shop_homework.yaml","source_metadata":{}},{"key":"noun_repair_shop_homework_q01_start","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\noun_repair_shop_homework.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"noun_repair_shop_homework_q01_finish","locale":"he","line_order":0,"content":"כל התוויות בקופסה מתוקנות, ומחר כל אחת תחזור לבעלים שלה.","line_format":"plain_text"},{"dialogue_key":"noun_repair_shop_homework_q01_finish","locale":"he","line_order":1,"content":"עכשיו אני יודעת שאפשר לסמוך עליכם בחנות גם כשאני לא כאן.","line_format":"plain_text"},{"dialogue_key":"noun_repair_shop_homework_q01_finish","locale":"he","line_order":2,"content":"זכרו: Noun = שם עצם, שם של אדם, חיה, מקום או דבר. למשל queen = מלכה, bird = ציפור, tower = מגדל, crown = כתר.","line_format":"plain_text"},{"dialogue_key":"noun_repair_shop_homework_q01_finish","locale":"he","line_order":3,"content":"כל הכבוד. עשיתם את שיעורי הבית לבד.","line_format":"plain_text"},{"dialogue_key":"noun_repair_shop_homework_q01_start","locale":"he","line_order":0,"content":"שלום שוב. מאז שהחנות נפתחה מחדש, מביאים אליה תוויות שבורות מכל הממלכה.","line_format":"plain_text"},{"dialogue_key":"noun_repair_shop_homework_q01_start","locale":"he","line_order":1,"content":"הבוקר הגיעה קופסה מלאה, ומחר הבעלים באים לקחת את התוויות שלהם.","line_format":"plain_text"},{"dialogue_key":"noun_repair_shop_homework_q01_start","locale":"he","line_order":2,"content":"היום אין שום דבר חדש, רק שמות שאתם כבר מכירים. הפעם תתקנו לבד - הקופסה מחכה לכם על שולחן התיקונים בפארק.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
